package net.civeira.phylax.features.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AuthorizationDetailsTypesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property authorization details types of oauth client ")
  void test_authorization_details_types_v_o_builder() {
    Assertions.assertFalse(
        AuthorizationDetailsTypesVO.nullValue().getAuthorizationDetailsTypes().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        AuthorizationDetailsTypesVO.tryFrom(null).getAuthorizationDetailsTypes().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        AuthorizationDetailsTypesVO.from("one").getAuthorizationDetailsTypes().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AuthorizationDetailsTypesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AuthorizationDetailsTypesVO.from("one").toString());
  }
}
